import urllib.request
import zipfile
import os
import urllib.error


def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    try:
        # Validate basic inputs
        if not isinstance(url, str) or not url.strip():
            return "URL Error: URL must be a non-empty string"

        # Ensure parent directories exist for the download path
        save_dir = os.path.dirname(os.path.abspath(save_path))
        if save_dir and not os.path.exists(save_dir):
            os.makedirs(save_dir, exist_ok=True)

        # Ensure extraction directory exists
        os.makedirs(extract_path, exist_ok=True)

        # Download the ZIP file
        try:
            with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
                while True:
                    chunk = response.read(8192)
                    if not chunk:
                        break
                    out_file.write(chunk)
        except urllib.error.URLError as e:
            reason = getattr(e, "reason", e)
            return f"URL Error: {reason}"

        # Extract the ZIP file
        try:
            with zipfile.ZipFile(save_path, "r") as zip_ref:
                zip_ref.extractall(extract_path)
        except zipfile.BadZipFile as e:
            return f"ZIP Error: {e}"
        except zipfile.LargeZipFile as e:
            return f"ZIP Error: {e}"
        except OSError as e:
            return f"File I/O Error: {e}"
        finally:
            # Always try to remove the downloaded archive
            try:
                if os.path.exists(save_path):
                    os.remove(save_path)
            except OSError:
                pass

        return os.path.abspath(extract_path)

    except OSError as e:
        return f"File I/O Error: {e}"
    except Exception as e:
        return f"Error: {e}"
